from openpyxl import load_workbook

# Load the workbook
wb = load_workbook('input.xlsx')
ws = wb['DATA']

# Get the value from cell I2
cell_i2 = ws['I2'].value

# Define the range to check for empty rows
start_row = 1
end_row = 19

# Function to delete empty rows within a specific range
def delete_empty_rows(start_row, end_row):
    rows_to_delete = []
    for row in range(start_row, end_row + 1):
        # Check if the row is empty (all cells in the row are empty)
        is_empty = True
        for col in ws.iter_cols(min_row=row, max_row=row, min_col=1, max_col=9):
            for cell in col:
                if cell.value is not None:
                    is_empty = False
                    break
            if not is_empty:
                break
        if is_empty:
            rows_to_delete.append(row)
    # Delete rows from bottom to top to avoid shifting issues
    for row in reversed(rows_to_delete):
        ws.delete_rows(row)

# Check if cell I2 is empty
if cell_i2 is None:
    # Delete all empty rows from the entire range
    delete_empty_rows(1, 19)
else:
    # Get the ID from cell I2
    target_id = cell_i2
    # Find the ranges based on the ID in column B
    ranges = []
    current_start = None
    for row in range(1, 19 + 1):
        cell_b = ws[f'B{row}'].value
        if cell_b == target_id:
            if current_start is None:
                current_start = row
        else:
            if current_start is not None:
                ranges.append((current_start, row - 1))
                current_start = None
    # If there's a remaining range at the end
    if current_start is not None:
        ranges.append((current_start, 19))
    # Delete empty rows within each range
    for start, end in ranges:
        delete_empty_rows(start, end)

# Save the workbook
wb.save('output.xlsx')
