from openpyxl import load_workbook

# Load the workbook
wb = load_workbook('input.xlsx')
ws = wb['Sheet1']

# Dictionary to store sums for each letter
letter_sums = {}

# Iterate through the rows starting from row 3 (assuming row 2 is headers)
for row in ws.iter_rows(min_row=3, max_col=9, max_row=17):
    for cell in row:
        # Check if the cell contains a value
        if cell.value:
            # Check if the cell value contains both letters and numbers
            if any(c.isalpha() for c in str(cell.value)) and any(c.isdigit() for c in str(cell.value)):
                # Extract the letter and number from the cell value
                letter = ''
                number = ''
                for c in str(cell.value):
                    if c.isalpha():
                        letter = c
                    elif c.isdigit():
                        number += c
                # Convert the number to an integer and add it to the corresponding letter's sum
                if letter not in letter_sums:
                    letter_sums[letter] = 0
                letter_sums[letter] += int(number)

# Write the computed sums to the answer range
for i, letter in enumerate(['A', 'B', 'C', 'D', 'E', 'F', 'G']):
    ws[f'B11:{chr(66 + i)}11'] = letter_sums.get(letter, 0)

# Save the workbook
wb.save('output.xlsx')
